    """Move each 4 downward one row; lower pattern expands diagonally to divider."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    div = next((r for r, row in enumerate(grid) if row and all(v == 2 for v in row)), None)
    if div is None:
        return out
    # Marks above the separator shift down by one cell, as demonstrated.
    for r in range(div):
        for c in range(w):
            if grid[r][c] == 4:
                out[r][c] = 0
                if r + 1 < div:
                    out[r + 1][c] = 4
    # Preserve marks below the separator (the demos show their fixed positions).
    for r in range(div + 1, h):
        for c in range(w):
            if grid[r][c] == 4:
                out[r][c] = 4
    return out
